#!/usr/bin/env bash
set -Eeuo pipefail

# Restores an encrypted bundle generated by export-mini-pc-migration.sh on a
# clean Ubuntu mini PC. It preserves any pre-existing target directories by
# renaming them instead of deleting them.

umask 077

if [ "${EUID:-$(id -u)}" -eq 0 ]; then
  echo "Ejecuta este script como tu usuario normal con acceso a sudo, no como root."
  exit 2
fi

BUNDLE_PATH="${1:-}"
TARGET_ROOT="${2:-$HOME/conectate-local-fallback}"
SIGNALING_ROOT="${SIGNALING_ROOT:-$HOME/signaling-server}"
STAMP="$(date -u +%Y%m%dT%H%M%SZ)"
WORK_DIR="$(mktemp -d)"

cleanup() {
  rm -rf -- "$WORK_DIR"
}
trap cleanup EXIT

usage() {
  echo "Uso: $0 /ruta/conectate-mini-pc-AAAAMMDD.tar.gz.enc [directorio-destino]"
}

read_passphrase() {
  if [ -n "${MIGRATION_PASSPHRASE:-}" ]; then
    printf '%s' "$MIGRATION_PASSPHRASE"
    return
  fi
  if [ ! -t 0 ]; then
    echo "ERROR: define MIGRATION_PASSPHRASE para una ejecución no interactiva." >&2
    exit 2
  fi
  local value
  read -r -s -p "Contraseña del paquete de migración: " value
  echo >&2
  test -n "$value" || { echo "ERROR: contraseña vacía." >&2; exit 2; }
  printf '%s' "$value"
}

install_docker() {
  if command -v docker >/dev/null && sudo docker compose version >/dev/null 2>&1; then
    return
  fi

  echo "==> Instalando Docker Engine y Compose"
  sudo apt-get update
  sudo apt-get install -y ca-certificates curl gnupg openssl
  sudo install -m 0755 -d /etc/apt/keyrings
  curl -fsSL https://download.docker.com/linux/ubuntu/gpg \
    | sudo gpg --dearmor --yes -o /etc/apt/keyrings/docker.gpg
  sudo chmod a+r /etc/apt/keyrings/docker.gpg
  # shellcheck disable=SC1091
  . /etc/os-release
  arch="$(dpkg --print-architecture)"
  echo "deb [arch=$arch signed-by=/etc/apt/keyrings/docker.gpg] https://download.docker.com/linux/ubuntu $VERSION_CODENAME stable" \
    | sudo tee /etc/apt/sources.list.d/docker.list >/dev/null
  sudo apt-get update
  sudo apt-get install -y docker-ce docker-ce-cli containerd.io docker-buildx-plugin docker-compose-plugin
  sudo systemctl enable --now docker
}

wait_for_container_health() {
  local container="$1"
  local attempts="${2:-60}"
  local status=""
  for _ in $(seq 1 "$attempts"); do
    status="$(sudo docker inspect --format='{{.State.Health.Status}}' "$container" 2>/dev/null || true)"
    [ "$status" = "healthy" ] && return 0
    sleep 2
  done
  echo "ERROR: $container no quedó saludable (estado: ${status:-desconocido})." >&2
  return 1
}

[ -n "$BUNDLE_PATH" ] || { usage; exit 2; }
BUNDLE_PATH="$(readlink -f "$BUNDLE_PATH")"
test -s "$BUNDLE_PATH" || { echo "ERROR: paquete no encontrado: $BUNDLE_PATH"; exit 2; }
command -v openssl >/dev/null || { sudo apt-get update && sudo apt-get install -y openssl; }

echo "==> Descifrando y validando paquete"
passphrase="$(read_passphrase)"
if ! MIGRATION_BUNDLE_PASSPHRASE="$passphrase" \
  openssl enc -d -aes-256-cbc -pbkdf2 -iter 250000 \
    -pass env:MIGRATION_BUNDLE_PASSPHRASE \
    -in "$BUNDLE_PATH" -out "$WORK_DIR/bundle.tar.gz"; then
  echo "WARN: no descifró con la contraseña directa; probando variante compatible con CRLF de Windows..." >&2
  MIGRATION_BUNDLE_PASSPHRASE="$(printf '%s\r' "$passphrase")" \
    openssl enc -d -aes-256-cbc -pbkdf2 -iter 250000 \
      -pass env:MIGRATION_BUNDLE_PASSPHRASE \
      -in "$BUNDLE_PATH" -out "$WORK_DIR/bundle.tar.gz"
fi
unset passphrase MIGRATION_BUNDLE_PASSPHRASE

if tar -tzf "$WORK_DIR/bundle.tar.gz" | grep -Eq '(^/|(^|/)\.\.(/|$))'; then
  echo "ERROR: el paquete contiene rutas inseguras."
  exit 2
fi
tar -xzf "$WORK_DIR/bundle.tar.gz" -C "$WORK_DIR"
PAYLOAD_DIR="$(find "$WORK_DIR" -mindepth 1 -maxdepth 1 -type d -name 'conectate-mini-pc-*' | head -n 1)"
test -d "$PAYLOAD_DIR"
(
  cd "$PAYLOAD_DIR"
  sha256sum --check SHA256SUMS
)
test -s "$PAYLOAD_DIR/runtime.env"
test -s "$PAYLOAD_DIR/secrets/firebase-service-account.json"
test -s "$PAYLOAD_DIR/postgres.dump"
test -s "$PAYLOAD_DIR/storage.tar.gz"

if grep -Eq '^(POSTGRES_PASSWORD|JWT_SECRET|ADMIN_SYNC_TOKEN)=($|change-this|cambia-esto)' "$PAYLOAD_DIR/runtime.env"; then
  echo "ERROR: runtime.env contiene secretos vacíos o de ejemplo."
  exit 2
fi

install_docker
sudo usermod -aG docker "$(id -un)"

for target in "$TARGET_ROOT" "$SIGNALING_ROOT"; do
  if [ -d "$target" ] && [ -n "$(find "$target" -mindepth 1 -maxdepth 1 -print -quit)" ]; then
    backup_target="$target.pre-migration-$STAMP"
    echo "==> Conservando $target como $backup_target"
    mv "$target" "$backup_target"
  fi
  mkdir -p "$target"
done

echo "==> Instalando código y secretos"
tar -xzf "$PAYLOAD_DIR/local-fallback-source.tar.gz" -C "$TARGET_ROOT"
tar -xzf "$PAYLOAD_DIR/signaling-source.tar.gz" -C "$SIGNALING_ROOT"
cp "$PAYLOAD_DIR/runtime.env" "$TARGET_ROOT/.env"
mkdir -p "$TARGET_ROOT/secrets"
cp "$PAYLOAD_DIR/secrets/firebase-service-account.json" \
  "$TARGET_ROOT/secrets/firebase-service-account.json"
chmod 600 "$TARGET_ROOT/.env" "$TARGET_ROOT/secrets/firebase-service-account.json"
chmod +x "$TARGET_ROOT/scripts/"*.sh
find "$TARGET_ROOT/db" -type d -exec chmod 755 {} \; 2>/dev/null || true
find "$TARGET_ROOT/db/init" -type f -exec chmod 644 {} \; 2>/dev/null || true

cd "$TARGET_ROOT"
sudo docker compose config --quiet

if sudo docker volume inspect conectate-fallback-db >/dev/null 2>&1; then
  echo "ERROR: ya existe el volumen conectate-fallback-db."
  echo "Este importador solo restaura en una mini PC limpia para no sobrescribir datos."
  exit 3
fi

echo "==> Creando PostgreSQL limpio"
sudo docker compose up -d db
wait_for_container_health conectate-local-fallback-db-main
sudo docker compose exec -T db dropdb -U conectate --if-exists --force conectate_fallback
sudo docker compose exec -T db createdb -U conectate conectate_fallback
sudo docker compose exec -T db pg_restore \
  -U conectate -d conectate_fallback --no-owner --no-privileges \
  < "$PAYLOAD_DIR/postgres.dump"

echo "==> Restaurando archivos subidos"
sudo docker volume create conectate-fallback-storage >/dev/null
sudo docker run --rm \
  -v conectate-fallback-storage:/data/storage \
  -v "$PAYLOAD_DIR:/migration:ro" \
  alpine:3.20 sh -eu -c \
  'find /data/storage -mindepth 1 -delete; tar -xzf /migration/storage.tar.gz -C /data/storage'

echo "==> Construyendo y levantando todos los servicios"
sudo docker compose up -d --build --remove-orphans
wait_for_container_health conectate-local-fallback-db-main
wait_for_container_health conectate-local-fallback-api-main
wait_for_container_health conectate-local-fallback-signaling-main
wait_for_container_health conectate-local-fallback-edge-main
wait_for_container_health conectate-local-fallback-realtime-main

ready="$(curl -fsS http://127.0.0.1:${FALLBACK_EDGE_PORT:-3080}/ready)"
echo "$ready" | grep -q '"ok":true'
echo "$ready" | grep -q '"configured":true'

echo "==> Instalando backups, watchdog y prueba semanal de restauración"
sg docker -c "cd '$TARGET_ROOT' && bash scripts/install-ubuntu-operations.sh"

table_count="$(sudo docker compose exec -T db psql -U conectate -d conectate_fallback -Atc \
  "SELECT count(*) FROM pg_tables WHERE schemaname NOT IN ('pg_catalog','information_schema');" \
  | tr -d '[:space:]')"
fcm_tokens="$(sudo docker compose exec -T db psql -U conectate -d conectate_fallback -Atc \
  'SELECT count(*) FROM fallback_fcm_tokens;' | tr -d '[:space:]')"

cat > "$TARGET_ROOT/.migration-import-complete" <<EOF
completedAt=$(date -u +%Y-%m-%dT%H:%M:%SZ)
sourceBundle=$(basename "$BUNDLE_PATH")
databaseTables=$table_count
fcmTokens=$fcm_tokens
EOF
chmod 600 "$TARGET_ROOT/.migration-import-complete"

echo "MIGRATION_IMPORT_OK=true"
echo "TARGET_ROOT=$TARGET_ROOT"
echo "DATABASE_TABLES=$table_count"
echo "FCM_TOKENS=$fcm_tokens"
echo "LOCAL_READY=http://127.0.0.1:${FALLBACK_EDGE_PORT:-3080}/ready"
echo "SIGUIENTE_PASO=Configura la entrada pública y cambia el endpoint dinámico antes del corte."
